                            ExampleLine(text: "Es ist am schönsten im Sommer.", meaning: "am + Superlativ."),
                            ExampleLine(text: "So teuer wie letzte Jahr.", meaning: "so + adj + wie = Gleichheit.")]),
                expressions: [
