                exercises: [
                            Exercise(id: "en-foundations-u4-there-is-e1", kind: "choice", prompt: "___ a pharmacy near here?", options: ["Is there", "Are there", "There is", "Has"], answers: ["Is there"], explain: "Singular questions: Is there …?"),
