                            ExampleLine(text: "Is it far from here?", meaning: "Ask about distance."),
                            ExampleLine(text: "About five minutes on foot.", meaning: "Time as distance.")]),
                expressions: [
                            TargetExpression(text: "How do I get to …?", meaning: "Ask for directions.", note: "…to the museum?"),
                            TargetExpression(text: "Go straight on.", meaning: "Keep walking.", note: "For two blocks."),
                            TargetExpression(text: "Turn left / right at …", meaning: "Where to change direction.", note: "at the traffic lights"),
                            TargetExpression(text: "on the left / on the right", meaning: "Which side it's on.", note: "The pharmacy is on your left."),
                            TargetExpression(text: "Is it far?", meaning: "Ask about distance.", note: "Answer: “Ten minutes on foot”."),
