public enum EnFoundationsNow {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-now", title: "Right now", subtitle: "What is happening", level: "A1", themes: [
                    ConversationTheme("rainy-window", "The rainy window", "Weather small talk", "cloud.rain", "Course", "You both watch the rain from a café window. Describe the weather and what people are doing outside.", 0),
                    ConversationTheme("busy-kitchen", "The busy kitchen", "What is happening now", "fork.knife", "Course", "You are cooking together. Say what everyone is doing right now — and who is doing nothing!", 1)], lessons: [
            Lesson(id: "en-foundations-now-continuous", title: "What is happening now", goal: "Describe actions happening at this moment with am/is/are + -ing.",
