                                PracticeQuestion(prompt: "We only need a little salt and a few olives.", expected: ["Got it: a little salt, a few olives."], focus: "a little vs a few", watch: "Countable? a few. Uncountable? a little.")]),
                exercises: [
                            Exercise(id: "en-foundations-u5-some-any-e1", kind: "choice", prompt: "We haven't got ___ milk.", options: ["any", "some", "a", "many"], answers: ["any"], explain: "Negatives take any."),
                            Exercise(id: "en-foundations-u5-some-any-e2", kind: "gap", prompt: "Can I have ___ water, please?", options: [], answers: ["some"], explain: "Requests take some, even as questions."),
                            Exercise(id: "en-foundations-u5-some-any-e3", kind: "order", prompt: "Say you need sugar for the cake.", options: [], answers: ["I need some sugar for the cake"], explain: "Affirmatives take some."),
                            Exercise(id: "en-foundations-u5-some-any-e4", kind: "written", prompt: "Say you need some bread.", options: [], answers: ["I need some bread", "I need to buy some bread"], explain: "some + uncountable: some bread, some water.")], skills: ["grammar:some-any", "grammar:countable-uncountable", "vocab:food", "function:go-shopping"], canDo: ["go-shopping"], prerequisites: ["grammar:plurals"]),
            Lesson(id: "en-foundations-u5-likes", title: "Like / love / hate + -ing", goal: "Talk about what you love, like and hate doing.",
                intro: LessonIntro(explanation: [
                            "After like, love, hate and don't like, the next verb takes -ing: “I love cooking.” “She hates waiting.”",
                            "Questions use do: “Do you like dancing?” Short answers: “Yes, I do.”",
                            "To soften, add really or quite: “I really love singing.” “I don't really like getting up early.”"], examples: [
                            ExampleLine(text: "I love reading.", meaning: "love + -ing."),
                            ExampleLine(text: "She likes walking to work.", meaning: "like + -ing."),
                            ExampleLine(text: "He hates getting up early.", meaning: "hate + -ing."),
                            ExampleLine(text: "Do you like dancing?", meaning: "Question with do."),
                            ExampleLine(text: "I don't like waiting.", meaning: "Negative + -ing."),
                            ExampleLine(text: "We really love travelling.", meaning: "Softener really.")]),
                expressions: [
                            TargetExpression(text: "I love + -ing", meaning: "Strong like.", note: "I love swimming."),
                            TargetExpression(text: "I like + -ing", meaning: "Mild like.", note: "I like cycling on Sundays."),
                            TargetExpression(text: "I hate + -ing", meaning: "Strong dislike.", note: "I hate queueing."),
                            TargetExpression(text: "I don't mind + -ing", meaning: "It's OK, neutral.", note: "I don't mind cooking."),
                            TargetExpression(text: "Do you like + -ing?", meaning: "Ask about tastes.", note: "Do you like hiking?"),
                            TargetExpression(text: "really / quite", meaning: "Turn the volume up or down.", note: "I quite like it.")],
                situation: "You plan a free Sunday together: propose activities and react with love, like, don't mind or hate until you agree on a plan.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "What do you love doing at weekends?", expected: ["I love <verb>ing."], focus: "love + -ing", watch: "“I love to swim” — with love, -ing is the everyday choice."),
                                PracticeQuestion(prompt: "Do you like cooking?", expected: ["Yes, I do.", "No, I don't. I hate cooking."], focus: "like questions", watch: "“Do you like cook?” — verb+ing after like."),
                                PracticeQuestion(prompt: "What's something you hate doing?", expected: ["I hate <verb>ing."], focus: "hate + -ing", watch: "“I hate get up” — “hate getting up”."),
                                PracticeQuestion(prompt: "Do you mind waiting?", expected: ["No, I don't mind waiting.", "Yes, I hate waiting."], focus: "don't mind", watch: "“I don't mind wait” — keep -ing."),
                                PracticeQuestion(prompt: "How much do you like films — a bit or a lot?", expected: ["I really like films.", "I quite like them."], focus: "softeners", watch: "“I like very much films” — “I really like films”."),
                                PracticeQuestion(prompt: "Your friend loves dancing but you don't. What do you say?", expected: ["I don't really like dancing.", "I don't like dancing, but thanks!"], focus: "polite dislike", watch: "Soften with really: “I don't really like…”.")]),
                exercises: [
                            Exercise(id: "en-foundations-u5-likes-e1", kind: "choice", prompt: "I love ___ to music.", options: ["listening", "listen", "listens", "to listening"], answers: ["listening"], explain: "Like/love/hate + verb-ing."),
                            Exercise(id: "en-foundations-u5-likes-e2", kind: "gap", prompt: "She hates ___ up early. (get)", options: [], answers: ["getting"], explain: "Short verb + consonant doubles: get → getting."),
                            Exercise(id: "en-foundations-u5-likes-e3", kind: "order", prompt: "Ask if the person enjoys cooking.", options: [], answers: ["Do you like cooking"], explain: "Do you like + -ing?"),
                            Exercise(id: "en-foundations-u5-likes-e4", kind: "written", prompt: "Say one thing you love doing.", options: [], answers: ["I love <verbing>", "I love <verb>ing"], explain: "I love + activity with -ing.")], skills: ["grammar:gerunds-infinitives", "vocab:hobbies", "function:express-opinion"], canDo: ["express-opinion"], prerequisites: ["grammar:present-simple"]),
            Lesson(id: "en-foundations-u5-cafe", title: "Ordering at a café", goal: "Order food and drink, ask for things and pay, in real café English.",
                intro: LessonIntro(explanation: [
                            "The magic order phrase is “I'd like …” (I would like) — polite and universal. “Can I have …, please?” works everywhere too.",
                            "The server asks: “Anything else?” Answer: “That's all, thanks.” Pay with: “The bill, please.”",
                            "Choices come fast: “Large or small?” “For here or to go?” Answer with a full mini-sentence: “Small, to go, please.”"], examples: [
                            ExampleLine(text: "I'd like a cappuccino, please.", meaning: "The polite order."),
                            ExampleLine(text: "Can I have a glass of water?", meaning: "Alternative order."),
                            ExampleLine(text: "Anything else?", meaning: "The server asks for more."),
                            ExampleLine(text: "That's all, thanks.", meaning: "Close the order."),
                            ExampleLine(text: "For here or to go?", meaning: "The classic choice."),
                            ExampleLine(text: "Can I have the bill, please?", meaning: "Ask to pay.")]),
                expressions: [
                            TargetExpression(text: "I'd like …, please.", meaning: "Polite order — would like.", note: "I'd like the soup."),
                            TargetExpression(text: "Can I have …, please?", meaning: "Order or ask for anything.", note: "Can I have a spoon?"),
                            TargetExpression(text: "Anything else?", meaning: "Server asks for more.", note: "Answer: “No, that's all”."),
                            TargetExpression(text: "For here or to go?", meaning: "Eat in or take away.", note: "To go, please."),
                            TargetExpression(text: "The bill, please.", meaning: "Ask to pay.", note: "Also: “Could we pay, please?”"),
                            TargetExpression(text: "Keep the change.", meaning: "Generous close.", note: "Small tip, big smile.")],
                situation: "A busy café at breakfast time: order for you and the learner, handle the server's questions and settle the bill.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Good morning! What can I get you?", expected: ["I'd like a <drink>, please.", "Can I have a <drink>, please?"], focus: "opening an order", watch: "“I want a coffee” — understandable, but “I'd like” is politer."),
                                PracticeQuestion(prompt: "Anything else?", expected: ["That's all, thanks.", "Yes, also a <item>, please."], focus: "closing the order", watch: "“Nothing more” — natural is “That's all, thanks”."),
                                PracticeQuestion(prompt: "For here or to go?", expected: ["For here, please.", "To go, please."], focus: "the classic choice", watch: "Answer the part they asked: here/to go."),
                                PracticeQuestion(prompt: "Large or small?", expected: ["Large, please.", "Small is fine."], focus: "size answers", watch: "“I take large” — “Large, please” is the café norm."),
                                PracticeQuestion(prompt: "Here you are — anything else for you two?", expected: ["Yes — the bill, please.", "No, thanks. Keep the change."], focus: "paying phrases", watch: "“Give me the bill” — “The bill, please” is polite."),
                                PracticeQuestion(prompt: "How was everything?", expected: ["Delicious, thank you!", "Very good, thanks."], focus: "polite close", watch: "One warm sentence closes the visit.")]),
                exercises: [
                            Exercise(id: "en-foundations-u5-cafe-e1", kind: "choice", prompt: "___ like a coffee, please.", options: ["I'd", "I", "Me", "Mine"], answers: ["I'd"], explain: "I'd like = polite want."),
                            Exercise(id: "en-foundations-u5-cafe-e2", kind: "gap", prompt: "Can I have the ___ , please? (la cuenta)", options: [], answers: ["bill"], explain: "The bill (UK) / the check (US)."),
                            Exercise(id: "en-foundations-u5-cafe-e3", kind: "order", prompt: "Ask for the menu politely.", options: [], answers: ["Can I have the menu, please"], explain: "Can I have … , please? works everywhere."),
                            Exercise(id: "en-foundations-u5-cafe-e4", kind: "written", prompt: "Order a tea politely.", options: [], answers: ["Can I have a tea, please", "I'd like a tea, please", "Can I have a tea"], explain: "Can I have / I’d like + drink + please.")], skills: ["function:order-food", "vocab:food", "grammar:countable-uncountable", "speaking:short-answer"], canDo: ["order-food"], prerequisites: ["grammar:some-any"])])
}

public enum EnFoundationsU6 {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-u6", title: "The past begins", subtitle: "Tell what happened", level: "A2", themes: [
                    ConversationTheme("weekend", "The weekend", "What happened", "sun.max", "Course", "Monday catch-up: tell each other what you really did at the weekend, moment by moment.", 0),
                    ConversationTheme("last-trip", "A trip to remember", "Tell the story", "airplane", "Course", "You swap stories of a memorable trip: where you were, what you did and how it ended.", 1)], lessons: [
            Lesson(id: "en-foundations-u6-was-were", title: "Was / were", goal: "Describe people, places and feelings in the past with was and were.",
                intro: LessonIntro(explanation: [
                            "Was and were are the past of to be. I/he/she/it → was. You/we/they → were. “I was at home.” “They were at the beach.”",
                            "Negatives: wasn't, weren't. Questions flip: “Was it good?” “Where were you?”",
                            "Anchor the story in time: yesterday, last night, last week, in 2020, this morning."], examples: [
                            ExampleLine(text: "I was tired yesterday.", meaning: "was with I."),
                            ExampleLine(text: "The film was great.", meaning: "was with it."),
                            ExampleLine(text: "We were at Ana's party.", meaning: "were with we."),
                            ExampleLine(text: "The streets weren't empty.", meaning: "Plural negative."),
                            ExampleLine(text: "Was the weather good?", meaning: "Past question."),
                            ExampleLine(text: "Where were you last night?", meaning: "Question word + were.")]),
                expressions: [
                            TargetExpression(text: "I was / he was …", meaning: "Past of be, singular.", note: "She was delighted."),
                            TargetExpression(text: "you were / they were", meaning: "Past of be, plural.", note: "They were neighbours."),
                            TargetExpression(text: "wasn't / weren't", meaning: "Past negatives.", note: "It wasn't my fault."),
                            TargetExpression(text: "Was it …? / Were you …?", meaning: "Past yes/no questions.", note: "Was it far?"),
                            TargetExpression(text: "yesterday / last night / last week", meaning: "Anchor the story in time.", note: "last weekend"),
                            TargetExpression(text: "It was amazing / awful.", meaning: "Give your verdict of the past.", note: "The concert? It was amazing.")],
                situation: "You bump into a friend who missed the neighbourhood party on Saturday: recount who was there, how it was and what wasn't good.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Where were you on Saturday?", expected: ["I was <place>.", "I was at home."], focus: "were with you", watch: "“I were at home” — with I use was."),
                                PracticeQuestion(prompt: "Was the party fun?", expected: ["Yes, it was.", "No, it wasn't."], focus: "was short answers", watch: "“Yes, was fun” — keep it: “Yes, it was”."),
                                PracticeQuestion(prompt: "Were there many people?", expected: ["Yes, there were lots.", "No, there weren't many."], focus: "were + there", watch: "“There was many” — plural: “there were”."),
                                PracticeQuestion(prompt: "How was the music?", expected: ["It was great.", "It was terrible!"], focus: "verdict with was", watch: "“It were good” — it takes was."),
                                PracticeQuestion(prompt: "I was so tired on Sunday. And you?", expected: ["I was tired too.", "I wasn't tired — I was full of energy."], focus: "wasn't", watch: "“I not tired” — past negative: “I wasn't tired”."),
                                PracticeQuestion(prompt: "Who was there from your class?", expected: ["<Name> was there.", "Nobody was there."], focus: "who + was", watch: "“Who were there” — who takes was here.")]),
                exercises: [
                            Exercise(id: "en-foundations-u6-was-were-e1", kind: "choice", prompt: "We ___ at home yesterday.", options: ["were", "was", "are", "did"], answers: ["were"], explain: "With we/you/they: were."),
                            Exercise(id: "en-foundations-u6-was-were-e2", kind: "gap", prompt: "The film ___ great.", options: [], answers: ["was"], explain: "Singular things: was."),
                            Exercise(id: "en-foundations-u6-was-were-e3", kind: "order", prompt: "Ask about last night.", options: [], answers: ["Where were you last night"], explain: "were + you for the past."),
                            Exercise(id: "en-foundations-u6-was-were-e4", kind: "written", prompt: "Describe el tiempo el fin de semana pasado.", options: [], answers: ["The weather was good at the weekend", "It was sunny at the weekend", "The weather was nice at the weekend"], explain: "was + adjective for past descriptions.")], skills: ["grammar:past-was-were", "vocab:feelings", "function:describe-past-events"], canDo: ["describe-past-events"], prerequisites: ["grammar:verb-be"]),
            Lesson(id: "en-foundations-u6-past", title: "Past simple: -ed", goal: "Tell what you and others did, with regular past forms and didn't.",
                intro: LessonIntro(explanation: [
                            "For finished actions, regular verbs add -ed: work → worked, play → played, watch → watched. The same form works for every person.",
                            "Questions and negatives use did + plain verb: “Did you walk?” “I didn't walk.” After did, no -ed: not “Did you walked?”",
                            "Spelling: love → loved (no e), study → studied (y→ied), stop → stopped (double p)."], examples: [
                            ExampleLine(text: "I worked late yesterday.", meaning: "-ed, all persons."),
                            ExampleLine(text: "She played tennis on Saturday.", meaning: "Same -ed with she."),
                            ExampleLine(text: "Did you watch the match?", meaning: "did + plain verb."),
                            ExampleLine(text: "We didn't stay long.", meaning: "didn't + plain verb."),
                            ExampleLine(text: "They studied all night.", meaning: "y → ied."),
                            ExampleLine(text: "It stopped suddenly.", meaning: "Double consonant.")]),
                expressions: [
                            TargetExpression(text: "verb + -ed", meaning: "Regular past, every person.", note: "I called you twice."),
                            TargetExpression(text: "Did you …?", meaning: "Past question, plain verb.", note: "Did you enjoy it?"),
                            TargetExpression(text: "I didn't …", meaning: "Past negative, plain verb.", note: "I didn't sleep well."),
                            TargetExpression(text: "Yes, I did. / No, I didn't.", meaning: "Short answers.", note: "Repeat did."),
                            TargetExpression(text: "y → ied", meaning: "study → studied, try → tried.", note: "We tried the new café."),
                            TargetExpression(text: "yesterday evening / last Friday", meaning: "Past time anchors.", note: "last Friday night")],
                situation: "You compare diaries from a chaotic Tuesday: what you did, what you didn't do, and what the other did first.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "What did you do yesterday evening?", expected: ["I <verb>ed …", "I watched TV and cooked dinner."], focus: "did + past answer", watch: "“I watch TV” — past answer needs -ed: “I watched”."),
                                PracticeQuestion(prompt: "Did you sleep well?", expected: ["Yes, I did.", "No, I didn't."], focus: "did short answers", watch: "The short answer repeats did: “Yes, I did”."),
                                PracticeQuestion(prompt: "Did you walk to work?", expected: ["No, I didn't. I cycled.", "Yes, I did."], focus: "didn't + plain verb", watch: "“I didn't walked” — after didn't, plain verb."),
                                PracticeQuestion(prompt: "What time did you finish work?", expected: ["I finished at <time>.", "I didn't finish until <time>."], focus: "past + time", watch: "“What time did you finished?” — after did, plain finish."),
                                PracticeQuestion(prompt: "Did you study English last week?", expected: ["Yes, I did. I studied on …", "No, I didn't study."], focus: "y→ied spelling", watch: "“I studyed” — study → studied."),
                                PracticeQuestion(prompt: "Your colleague — did she call you?", expected: ["Yes, she did.", "No, she didn't call."], focus: "third person past", watch: "“Did she called” — after did, plain call.")]),
                exercises: [
                            Exercise(id: "en-foundations-u6-past-e1", kind: "choice", prompt: "I ___ TV last night.", options: ["watched", "watch", "watching", "am watch"], answers: ["watched"], explain: "Regular past: watch → watched."),
                            Exercise(id: "en-foundations-u6-past-e2", kind: "gap", prompt: "She didn't ___ the email. (receive)", options: [], answers: ["receive"], explain: "After didn't the verb stays in base form."),
                            Exercise(id: "en-foundations-u6-past-e3", kind: "order", prompt: "Say they got here late yesterday.", options: [], answers: ["They arrived late yesterday"], explain: "arrive → arrived; no did when the past is on the verb."),
                            Exercise(id: "en-foundations-u6-past-e4", kind: "written", prompt: "Say you worked on Saturday.", options: [], answers: ["I worked on Saturday", "On Saturday I worked"], explain: "work → worked.")], skills: ["grammar:past-simple-regular", "grammar:past-simple-irregular", "function:describe-past-events", "pron:past-ed"], canDo: ["describe-past-events"], prerequisites: ["grammar:past-was-were"]),
            Lesson(id: "en-foundations-u6-weekend", title: "Your weekend (repaso)", goal: "Tell the story of your weekend in order — past be, past verbs, time anchors — and ask about someone else's.",
                intro: LessonIntro(explanation: [
                            "A weekend story has three parts: where you were (was/were), what you did (past -ed), and how it was (was + opinion).",
                            "Order it with time anchors: on Saturday morning, then, in the evening, later, finally.",
                            "Keep the conversation alive: ask back with “What about you?” or “Did you …?”"], examples: [
                            ExampleLine(text: "On Friday I was at home — I was exhausted.", meaning: "Part 1: where + how."),
                            ExampleLine(text: "On Saturday I visited my parents.", meaning: "Part 2: past action."),
                            ExampleLine(text: "We walked in the park and talked for hours.", meaning: "Two past verbs, one story."),
                            ExampleLine(text: "In the evening I watched a film.", meaning: "Time anchor + past."),
                            ExampleLine(text: "It was a really good weekend.", meaning: "Part 3: the verdict."),
                            ExampleLine(text: "What about you? What did you do?", meaning: "Ask it back.")]),
                expressions: [
                            TargetExpression(text: "On Saturday morning, …", meaning: "Open the story with a time.", note: "…I played padel."),
                            TargetExpression(text: "First …, then …, later …", meaning: "Sequence the actions.", note: "Then we had lunch."),
                            TargetExpression(text: "I visited / called / watched …", meaning: "Regular past actions.", note: "I called my brother."),
                            TargetExpression(text: "It was really + adjective", meaning: "Give your verdict.", note: "It was really relaxing."),
                            TargetExpression(text: "What about you?", meaning: "Return the question.", note: "The conversation keeps flowing."),
                            TargetExpression(text: "That sounds + adjective", meaning: "React to the other's story.", note: "That sounds fun!")],
                situation: "Monday coffee with a friend: take turns telling your weekends, react, and ask at least two questions back.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "So — how was your weekend?", expected: ["It was <adjective>. On Saturday I …", "Really good, thanks!"], focus: "verdict + story opener", watch: "Start with the verdict, then the story."),
                                PracticeQuestion(prompt: "What did you do on Saturday?", expected: ["I <verb>ed … First …, then …"], focus: "past actions in order", watch: "Use -ed for regular verbs and an order word."),
                                PracticeQuestion(prompt: "Were you with friends or alone?", expected: ["I was with <people>.", "I was on my own."], focus: "was/were recap", watch: "“I was with” — was works with I."),
                                PracticeQuestion(prompt: "That sounds nice! Did you eat out?", expected: ["Yes, we did — we tried a new place.", "No, we didn't. We cooked at home."], focus: "did questions about the story", watch: "“Yes, we eat out” — past short answer: “Yes, we did”."),
                                PracticeQuestion(prompt: "What about Sunday?", expected: ["On Sunday I …", "Sunday was quieter — I …"], focus: "extending the story", watch: "Another time anchor, another scene."),
                                PracticeQuestion(prompt: "OK, your turn — ask me about my weekend.", expected: ["What did you do?", "How was your weekend?"], focus: "asking back", watch: "A conversation needs a return serve: ask one question.")]),
                exercises: [
                            Exercise(id: "en-foundations-u6-weekend-e1", kind: "choice", prompt: "___ you have a good weekend?", options: ["Did", "Was", "Were", "Do"], answers: ["Did"], explain: "have is a normal verb: questions need Did."),
                            Exercise(id: "en-foundations-u6-weekend-e2", kind: "gap", prompt: "We ___ so tired on Sunday.", options: [], answers: ["were"], explain: "Past be with we: were."),
                            Exercise(id: "en-foundations-u6-weekend-e3", kind: "order", prompt: "Start your Saturday story.", options: [], answers: ["On Saturday I met my friends"], explain: "Time anchor first: On Saturday …"),
                            Exercise(id: "en-foundations-u6-weekend-e4", kind: "written", prompt: "Tell one thing you did last weekend.", options: [], answers: ["I <verbed> last weekend", "Last weekend I <verbed>", "On Saturday I <verbed>"], explain: "Past verb + time anchor.")], skills: ["grammar:past-simple-irregular", "grammar:time-expressions", "function:tell-a-story", "speaking:tell-past-story"], canDo: ["tell-a-story"], prerequisites: ["grammar:past-simple-regular"])])
}

public enum EnFoundationsCompare {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-compare", title: "Comparing & choosing", subtitle: "Which one is better?", level: "A2", themes: [
                    ConversationTheme("two-flats", "Two flats, one choice", "Compare and decide", "house", "Course", "You visit two flats to rent. Compare rooms, price, light and noise — then choose one together.", 0),
                    ConversationTheme("gift-debate", "The gift debate", "The best present", "gift", "Course", "You are choosing a birthday present for a friend. Compare ideas and agree on the best one.", 1)], lessons: [
            Lesson(id: "en-foundations-compare-comparatives", title: "Comparatives", goal: "Compare two things with -er/more … than.",
                intro: LessonIntro(explanation: [
                            "Short adjectives take -er: cheap → cheaper, big → bigger, busy → busier. Long adjectives take more: more expensive, more comfortable.",
                            "The comparison word is than: “This flat is cheaper than that one.” “The kitchen is bigger than the bedroom.”",
                            "Irregulars: good → better, bad → worse, far → further."], examples: [
                            ExampleLine(text: "This café is cheaper than that one.", meaning: "cheap → cheaper."),
                            ExampleLine(text: "Trains are more comfortable than buses.", meaning: "Long adjective → more."),
                            ExampleLine(text: "My flat is bigger than yours.", meaning: "big → bigger (double the g)."),
                            ExampleLine(text: "Today is busier than yesterday.", meaning: "busy → busier (y → i)."),
                            ExampleLine(text: "This book is better than the film.", meaning: "Irregular: better."),
                            ExampleLine(text: "Is the market cheaper than the supermarket?", meaning: "Question with comparatives.")]),
                expressions: [
                            TargetExpression(text: "… -er than …", meaning: "Compare short adjectives.", note: "cheaper, older, faster."),
                            TargetExpression(text: "more … than …", meaning: "Compare long adjectives.", note: "more modern, more quiet? → noisier!"),
                            TargetExpression(text: "better / worse than", meaning: "The two irregulars you need most.", note: "Never “more good”."),
                            TargetExpression(text: "much … -er / much more …", meaning: "Make the difference big.", note: "much cheaper = mucho más barato."),
                            TargetExpression(text: "Which one do you prefer?", meaning: "Ask for a choice.", note: "I prefer the small one."),
                            TargetExpression(text: "… than I expected.", meaning: "Compare with an expectation.", note: "nicer than I expected.")],
                situation: "You and a friend compare two cafés near work: price, size, coffee, noise — and choose where to go today.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Compare two flats: the second one is modern, the first isn't. (sentence)", expected: ["The second flat is more modern than the first."], focus: "more + long adjective", watch: "“moderner” doesn't exist — long adjectives take more."),
                                PracticeQuestion(prompt: "The bus takes 40 minutes, the train takes 25. Compare them.", expected: ["The train is faster than the bus.", "The bus is slower than the train."], focus: "-er than", watch: "Keep than in the sentence: “faster than”."),
                                PracticeQuestion(prompt: "Which is correct: “more good” or “better”?", expected: ["better"], focus: "irregular comparative", watch: "good → better, bad → worse — always irregular."),
                                PracticeQuestion(prompt: "The rent is 800; you expected 600. React.", expected: ["It's more expensive than I expected.", "The rent is higher than I expected."], focus: "than I expected", watch: "higher for prices, more expensive also works."),
