public enum EnFoundationsExperiences {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-experiences", title: "Experiences & stories", subtitle: "Have you ever…?", level: "B1", themes: [
                    ConversationTheme("travel-bucket-list", "The bucket list", "Have you ever…?", "airplane", "Course", "You compare life experiences: places you have and haven't been, things you have and haven't tried.", 0),
                    ConversationTheme("story-night", "Story night", "What was happening?", "moon.stars", "Course", "You tell a story with background: what was happening when something unexpected occurred.", 1)], lessons: [
            Lesson(id: "en-foundations-experiences-present-perfect", title: "Present perfect: experiences", goal: "Talk about life experiences with have/has + past participle, without saying when.",
                intro: LessonIntro(explanation: [
                            "Experiences without a time use have/has + past participle: “I've visited Rome. She's never tried sushi. Have you been to Japan?”",
                            "The moment you say WHEN, switch to past simple: “I've been to Rome. I went there in 2019.”",
                            "Participates are irregular often: be → been, see → seen, go → gone/been, eat → eaten, do → done."], examples: [
                            ExampleLine(text: "I've never been to Asia.", meaning: "A life experience (not yet!)."),
                            ExampleLine(text: "Have you ever tried paella?", meaning: "ever = in your life."),
                            ExampleLine(text: "She's seen that film three times.", meaning: "Repeated experience."),
                            ExampleLine(text: "We've just finished dinner.", meaning: "just = a moment ago."),
                            ExampleLine(text: "I've already packed, but I haven't printed the tickets.", meaning: "already / not yet."),
                            ExampleLine(text: "I went to Rome in 2019.", meaning: "WHEN given → past simple.")]),
                expressions: [
                            TargetExpression(text: "I've (never/ever/already) …", meaning: "Experience, no date.", note: "I've never driven a van."),
                            TargetExpression(text: "Have you ever …?", meaning: "The classic experience question.", note: "Reply: Yes, I have / No, I haven't."),
                            TargetExpression(text: "I've just …", meaning: "Very recent.", note: "I've just arrived."),
                            TargetExpression(text: "… twice / three times", meaning: "Count the experience.", note: "I've read it twice."),
                            TargetExpression(text: "gone to vs been to", meaning: "gone = still there; been = visited and returned.", note: "She's gone to Rome (not back yet)."),
                            TargetExpression(text: "When? → past simple", meaning: "The golden switch rule.", note: "I've been to Peru. I went in 2018.")],
                situation: "You meet a traveller at a hostel: swap life experiences with Have you ever…? and ask follow-up questions with past simple when they give a when.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Ask a traveller if they have ever visited Japan.", expected: ["Have you ever been to Japan?", "Have you ever visited Japan?"], focus: "Have you ever…?", watch: "“Did you ever visit…?” is possible in AmE, but “Have you ever…?” is the safest form."),
                                PracticeQuestion(prompt: "Answer negatively: you have never tried surfing.", expected: ["I've never tried surfing.", "I have never tried surfing."], focus: "never + participle", watch: "“I've never tried to surf” changes meaning slightly; keep “tried surfing”."),
                                PracticeQuestion(prompt: "Say you visited Rome in 2019 (mention the year).", expected: ["I went to Rome in 2019."], focus: "when → past simple", watch: "“I've gone to Rome in 2019” — a finished time forbids the present perfect."),
                                PracticeQuestion(prompt: "Your friend is not here — she went to the airport. Say it two ways.", expected: ["She's gone to the airport.", "She has gone to the airport."], focus: "gone to", watch: "“She's been to the airport” means she went and came back."),
                                PracticeQuestion(prompt: "Say you have seen that film three times.", expected: ["I've seen that film three times.", "I have seen that film three times."], focus: "counting experiences", watch: "“I saw it three times” needs a past anchor; without one, prefer the present perfect."),
