public enum EnFoundationsConnections {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-connections", title: "Opinions & connections", subtitle: "If, which, however", level: "B1", themes: [
                    ConversationTheme("plan-b", "Plan B", "If it rains…", "cloud.bolt", "Course", "Your outdoor plan is at risk. Negotiate conditionals: if this happens, we'll do that.", 0),
                    ConversationTheme("movie-debate", "The film debate", "Which one? However…", "film", "Course", "You review a film together: describe scenes with relative clauses and connect opinions with however and although.", 1)], lessons: [
            Lesson(id: "en-foundations-connections-first-conditional", title: "First conditional", goal: "Talk about real future possibilities with if + present, will + verb.",
                intro: LessonIntro(explanation: [
                            "Real future conditions: “If it rains, we'll stay in.” The if-clause uses present simple; the result uses will.",
                            "Order can flip, but the comma disappears: “We'll stay in if it rains.” Never will inside the if-clause.",
                            "Variations: “If it rains, we might stay in / we can stay in / let's stay in.”"], examples: [
