                            TargetExpression(text: "… if + present", meaning: "Result first, no comma.", note: "I'll call you if I'm late."),
                            TargetExpression(text: "If not, … / Otherwise, …", meaning: "The other branch.", note: "Otherwise we'll drive."),
                            TargetExpression(text: "might / can + verb", meaning: "Softer results.", note: "If it's cheap, we might buy it."),
                            TargetExpression(text: "What will happen if …?", meaning: "Ask about consequences.", note: "…if the flight is cancelled?"),
                            TargetExpression(text: "as long as / unless", meaning: "Condition cousins.", note: "unless = if not.")],
