                                PracticeQuestion(prompt: "The bus may not come. Predict lateness.", expected: ["If the bus doesn't come, we'll be late.", "We'll be late if the bus doesn't come."], focus: "negative condition", watch: "“If the bus won't come” — present simple after if."),
                                PracticeQuestion(prompt: "Offer an exchange of help.", expected: ["If you help me, I'll help you."], focus: "exchange", watch: "Both halves stay simple: present + will."),
                                PracticeQuestion(prompt: "Ask about a cancelled flight. (what / you / do)", expected: ["What will you do if the flight is cancelled?"], focus: "the conditional question", watch: "will goes in the result question, not after if."),
                                PracticeQuestion(prompt: "Soften the result: if it's cheap, maybe buy it.", expected: ["If it's cheap, I might buy it.", "If it's cheap, we might buy it."], focus: "might", watch: "might + base verb: “might to buy” is wrong."),
                                PracticeQuestion(prompt: "Say the alternative: no picnic → restaurant.", expected: ["If we can't have a picnic, we'll go to a restaurant.", "Otherwise, we'll go to a restaurant."], focus: "otherwise", watch: "Otherwise connects to the previous sentence's failure.")]),
                exercises: [
