                            Exercise(id: "en-foundations-connections-first-conditional-e2", kind: "gap", prompt: "I'll call you if I ___ late. (be)", options: [], answers: ["am", "'m"], explain: "Present simple after if: if I am late."),
                            Exercise(id: "en-foundations-connections-first-conditional-e3", kind: "order", prompt: "Ask about a snow plan.", options: [], answers: ["What will you do if it snows"], explain: "Question word + will + you + do + if + present."),
                            Exercise(id: "en-foundations-connections-first-conditional-e4", kind: "written", prompt: "Fix: “If it will rain, we stay in.”", options: [], answers: ["if it rains we'll stay in", "if it rains we will stay in"], explain: "Present after if, will in the result.")], skills: ["grammar:first-conditional", "grammar:future-forms", "function:make-future-plans", "function:solve-problems"], canDo: ["make-future-plans"], prerequisites: ["grammar:present-simple", "grammar:going-to"]),
            Lesson(id: "en-foundations-connections-relative-clauses", title: "Relative clauses", goal: "Join ideas with who, which, that and where.",
                intro: LessonIntro(explanation: [
                            "who joins people, which joins things, that joins both (informal): “The woman who lives upstairs is a doctor.” “The book which won the prize…”",
                            "where joins places: “That's the café where we met.”",
                            "Shortened clauses: “The man standing there” (= who is standing). No double subject: “the book which won” not “the book which it won”."], examples: [
