                            TargetExpression(text: "the thing which/that …", meaning: "Identify things.", note: "The app which tracks habits."),
                            TargetExpression(text: "the place where …", meaning: "Identify places.", note: "the street where I grew up."),
                            TargetExpression(text: "(that) … as object", meaning: "The joining word can vanish.", note: "the film (that) we saw."),
                            TargetExpression(text: "…, which …", meaning: "Comment on the whole sentence.", note: "He was late, which annoyed everyone."),
