public enum EnFoundationsViewpoints {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-viewpoints", title: "Viewpoints", subtitle: "Argue, report, imagine", level: "B2", themes: [
                    ConversationTheme("debate-club", "Debate night", "Take a side", "person.3", "Course", "You debate a topical question: state your position, imagine alternatives, report what the data says.", 0),
                    ConversationTheme("negotiation-table", "The negotiation", "Find the middle", "scale.3d", "Course", "You negotiate a work arrangement: conditions, consequences and a deal both sides can accept.", 1)], lessons: [
            Lesson(id: "en-foundations-viewpoints-second-conditional", title: "Second conditional", goal: "Imagine unreal presents and alternatives with if + past, would + verb.",
                intro: LessonIntro(explanation: [
                            "Unreal presents use if + past simple, would + verb: “If I had more time, I would learn the piano.” The time is now/forward — the past form only marks unreality.",
                            "Questions: “What would you do if you lost your job?” I'd = I would.",
                            "Softer advice uses would in the result: “If I were you, I'd negotiate.” Note the fixed phrase If I were you."], examples: [
                            ExampleLine(text: "If I won the lottery, I would travel for a year.", meaning: "An unreal present."),
                            ExampleLine(text: "If I were you, I'd ask for a raise.", meaning: "Advice with were."),
                            ExampleLine(text: "Would you move abroad if you got the chance?", meaning: "Question form."),
                            ExampleLine(text: "I wouldn't say that if I weren't sure.", meaning: "Negative on both sides."),
                            ExampleLine(text: "If we had a bigger budget, we could hire help.", meaning: "could = would be able to."),
                            ExampleLine(text: "Compare: “If it rains, we'll stay” (real) vs “If it rained, we'd stay” (unlikely).", meaning: "First vs second conditional.")]),
                expressions: [
                            TargetExpression(text: "If + past, would + verb", meaning: "Unreal present.", note: "If I had time, I would cook."),
                            TargetExpression(text: "If I were you, I'd …", meaning: "The advice formula.", note: "were, not was, in formal English."),
                            TargetExpression(text: "What would you do if …?", meaning: "The hypothetical question.", note: "Perfect for debates."),
                            TargetExpression(text: "I'd never …", meaning: "A firm unreal negative.", note: "I'd never lie to a client."),
                            TargetExpression(text: "could / might instead of would", meaning: "Ability or possibility in the result.", note: "If we left now, we could catch it."),
                            TargetExpression(text: "Compare with first conditional", meaning: "Real vs imaginary.", note: "If I win… (possible) vs If I won… (fantasy).")],
                situation: "A debate table: what would you do with a year off, a sudden fortune, a job abroad? Defend your hypotheticals and challenge theirs.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Imagine you had a year off. What would you do?", expected: ["If I had a year off, I would <activity>.", "I'd <activity>."], focus: "if + past, would", watch: "“If I would have a year” — never would in the if-clause."),
                                PracticeQuestion(prompt: "Give advice to a friend who earns too little. (If I were you…)", expected: ["If I were you, I'd ask for a raise.", "If I were you, I would look for another job."], focus: "If I were you", watch: "The fixed advice formula uses were."),
                                PracticeQuestion(prompt: "Ask about your friend's hypothetical move abroad.", expected: ["Would you move abroad if you got the chance?"], focus: "would question", watch: "would in the result question; past in the if-clause."),
                                PracticeQuestion(prompt: "Say what is possible, not certain: if we left now / catch the train.", expected: ["If we left now, we could catch the train."], focus: "could in the result", watch: "could replaces would for possibility."),
                                PracticeQuestion(prompt: "Contrast real vs imaginary: rain tomorrow / money for a trip.", expected: ["If it rains tomorrow, we'll cancel. If I had money for a trip, I'd go today."], focus: "first vs second", watch: "Real future takes present+will; fantasy takes past+would."),
                                PracticeQuestion(prompt: "Firm unreal negative: lie to a client.", expected: ["I'd never lie to a client.", "I would never lie to a client."], focus: "I'd never", watch: "would + never + base verb.")]),
                exercises: [
                            Exercise(id: "en-foundations-viewpoints-second-conditional-e1", kind: "choice", prompt: "If I ___ more time, I would learn the piano.", options: ["had", "have", "would have", "will have"], answers: ["had"], explain: "Unreal present: if + past simple."),
                            Exercise(id: "en-foundations-viewpoints-second-conditional-e2", kind: "gap", prompt: "If I were you, I ___ ask for a raise.", options: [], answers: ["would", "'d"], explain: "would in the result: I'd ask."),
                            Exercise(id: "en-foundations-viewpoints-second-conditional-e3", kind: "order", prompt: "Ask the hypothetical question. (move / would / if / you / abroad / the chance / you / got)", options: [], answers: ["Would you move abroad if you got the chance"], explain: "would question + if + past."),
                            Exercise(id: "en-foundations-viewpoints-second-conditional-e4", kind: "written", prompt: "Fix: “If I would have time, I would cook.”", options: [], answers: ["if i had time i would cook"], explain: "The if-clause takes had, never would have.")], skills: ["grammar:second-conditional", "grammar:first-conditional", "function:express-opinion", "speaking:justify-opinion"], canDo: ["express-opinion"], prerequisites: ["grammar:past-simple-irregular", "grammar:first-conditional"]),
            Lesson(id: "en-foundations-viewpoints-passive", title: "The passive: reporting", goal: "Report information with is/are/was/were + past participle when the doer is unknown or unimportant.",
                intro: LessonIntro(explanation: [
                            "Passive = be + past participle: “The bridge was built in 1900.” “These shoes are made in Portugal.” The doer disappears or moves to a by-phrase.",
                            "Use it when the doer is obvious, unknown or unimportant — the classic register of news, reports and instructions.",
                            "Questions and negatives behave like be: “Was it built recently?” “It isn't sold here.”"], examples: [
                            ExampleLine(text: "The results will be published tomorrow.", meaning: "Future passive."),
                            ExampleLine(text: "This bridge was built in 1900.", meaning: "Past passive."),
                            ExampleLine(text: "These shoes are made in Portugal.", meaning: "Present passive."),
                            ExampleLine(text: "The novel was written by a nurse.", meaning: "by + the important doer."),
                            ExampleLine(text: "Payment must be made in advance.", meaning: "Modal + passive."),
                            ExampleLine(text: "Was the email sent?", meaning: "Passive question.")]),
                expressions: [
                            TargetExpression(text: "is/are + participle", meaning: "Present facts.", note: "The office is cleaned daily."),
                            TargetExpression(text: "was/were + participle", meaning: "Past events.", note: "It was designed by Gaudí."),
                            TargetExpression(text: "will be + participle", meaning: "Future plans.", note: "The report will be shared on Monday."),
                            TargetExpression(text: "must be + participle", meaning: "Rules and instructions.", note: "Tickets must be validated."),
                            TargetExpression(text: "by + doer", meaning: "Only when the doer matters.", note: "Hamlet was written by Shakespeare."),
                            TargetExpression(text: "It is said that …", meaning: "Reporting without a source.", note: "It is said that the lake is bottomless.")],
                situation: "You present a short report about your town's history: what was built, what is produced there and what will be opened next year.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Report a past fact: they built the theatre in 1921. (passive)", expected: ["The theatre was built in 1921."], focus: "was + participle", watch: "“was build” — the participle is built."),
                                PracticeQuestion(prompt: "State a present fact: they make these shoes in Portugal. (passive)", expected: ["These shoes are made in Portugal."], focus: "are + participle", watch: "“are make” — participle, not base form."),
                                PracticeQuestion(prompt: "Announce a plan: they will publish the results tomorrow. (passive)", expected: ["The results will be published tomorrow."], focus: "will be + participle", watch: "“will published” — be comes first: will be published."),
                                PracticeQuestion(prompt: "State a rule: you must validate tickets. (passive)", expected: ["Tickets must be validated."], focus: "must be", watch: "Modal + be + participle."),
                                PracticeQuestion(prompt: "The doer matters here. Join: “Shakespeare wrote Hamlet.” Keep Shakespeare. (passive)", expected: ["Hamlet was written by Shakespeare."], focus: "by + doer", watch: "by appears only when the doer is important information."),
                                PracticeQuestion(prompt: "Ask about a past event in passive form. (the email / send)", expected: ["Was the email sent?"], focus: "passive question", watch: "be moves to the front: Was it sent?")]),
                exercises: [
                            Exercise(id: "en-foundations-viewpoints-passive-e1", kind: "choice", prompt: "These computers ___ in Taiwan.", options: ["are made", "are making", "made", "is made"], answers: ["are made"], explain: "Plural present passive: are made."),
                            Exercise(id: "en-foundations-viewpoints-passive-e2", kind: "gap", prompt: "The parcel ___ ___ delivered tomorrow. (will, passive)", options: [], answers: ["will be"], explain: "will be + participle."),
                            Exercise(id: "en-foundations-viewpoints-passive-e3", kind: "order", prompt: "Report the rule.", options: [], answers: ["Tickets must be validated before boarding"], explain: "modal + be + participle."),
                            Exercise(id: "en-foundations-viewpoints-passive-e4", kind: "written", prompt: "Fix: “The house was build in 1990.”", options: [], answers: ["the house was built in 1990"], explain: "build → built: the participle.")], skills: ["grammar:passive-intro", "grammar:past-simple-regular", "function:talk-about-work", "writing:email"], canDo: ["talk-about-work"], prerequisites: ["grammar:past-simple-regular", "grammar:verb-be"]),
            Lesson(id: "en-foundations-viewpoints-negotiation", title: "Negotiating", goal: "Negotiate politely: propose conditions, concede ground and close a deal.",
                intro: LessonIntro(explanation: [
                            "Proposals soften with could/would: “Could we possibly move the deadline?” “Would it help if I took the night shift?”",
                            "Concede with a condition: “That works if…”, “As long as…, I'm happy to…”. Push back without conflict: “I see your point, however…”",
                            "Close: “Shall we say…?”, “So we agree on…”, “I think we have a deal.”"], examples: [
                            ExampleLine(text: "Could we possibly start at ten?", meaning: "A softened proposal."),
                            ExampleLine(text: "That works if the report arrives on Thursday.", meaning: "A conditional yes."),
                            ExampleLine(text: "As long as I keep Fridays free, I'm happy to travel.", meaning: "As long as = condition."),
                            ExampleLine(text: "I see your point; however, the budget is fixed.", meaning: "Pushback without conflict."),
                            ExampleLine(text: "What if we split the difference?", meaning: "A middle-ground move."),
                            ExampleLine(text: "Shall we say thirty percent?", meaning: "The closing formula.")]),
                expressions: [
                            TargetExpression(text: "Could we possibly …?", meaning: "A polite proposal.", note: "possibly = extra soft."),
                            TargetExpression(text: "That works if …", meaning: "Yes, with a condition.", note: "Condition first, then agreement."),
                            TargetExpression(text: "as long as …", meaning: "Your red lines.", note: "As long as costs stay under X."),
                            TargetExpression(text: "I see your point; however …", meaning: "Respectful disagreement.", note: "Acknowledge, then contrast."),
                            TargetExpression(text: "What if we …?", meaning: "Offer a middle path.", note: "What if we split the costs?"),
                            TargetExpression(text: "Shall we say …?", meaning: "Close the deal.", note: "Numbers finish negotiations.")],
                situation: "You negotiate a remote-work arrangement with your manager: propose, concede, push back once and close with a concrete deal.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Politely propose a later start time.", expected: ["Could we possibly start at ten?", "Would it be possible to start later?"], focus: "softened proposal", watch: "Bare commands sound abrupt in negotiation; use could/would."),
                                PracticeQuestion(prompt: "Accept travelling, with one condition. (as long as)", expected: ["That works as long as I keep Fridays free.", "As long as costs are covered, I'm happy to travel."], focus: "as long as", watch: "as long as + present simple for your condition."),
                                PracticeQuestion(prompt: "Disagree respectfully with a tight deadline.", expected: ["I see your point; however, the deadline is too tight.", "I understand, however we need two more days."], focus: "acknowledge + however", watch: "Acknowledge first — however lands softer after agreement words."),
                                PracticeQuestion(prompt: "Offer a middle ground on price.", expected: ["What if we split the difference?", "What if we meet in the middle?"], focus: "what if", watch: "what if + present simple proposes the path."),
                                PracticeQuestion(prompt: "Close the deal on a number. (thirty percent)", expected: ["Shall we say thirty percent?"], focus: "closing", watch: "shall we say + the final number."),
                                PracticeQuestion(prompt: "State the deal you both reached.", expected: ["So we agree on: remote Mondays and a Thursday report.", "So we agree: I travel twice a month, you cover the costs."], focus: "summarising", watch: "Good negotiators summarise: “So we agree on…”.")]),
                exercises: [
                            Exercise(id: "en-foundations-viewpoints-negotiation-e1", kind: "choice", prompt: "___ we possibly move the meeting to Thursday?", options: ["Could", "Must", "Will", "Should"], answers: ["Could"], explain: "Could we possibly…? is the softest proposal."),
                            Exercise(id: "en-foundations-viewpoints-negotiation-e2", kind: "gap", prompt: "That works ___ ___ as the budget is approved. (2 words: condition)", options: [], answers: ["as long", "so long"], explain: "as long as / so long as = siempre que."),
                            Exercise(id: "en-foundations-viewpoints-negotiation-e3", kind: "order", prompt: "Respectfully disagree.", options: [], answers: ["I see your point however the budget is fixed"], explain: "Acknowledge, then contrast."),
